import { type KeyboardEvent, type ReactNode, useMemo } from "react";
import { cn } from "@/lib/cn";
import { VIRTUALIZE_THRESHOLD, flattenVisible } from "@/lib/trace/flatten";
import type { TraceSpan } from "@/lib/trace/types";
import { SpanTreeRow } from "@/components/ui/span-tree-row";
import { SpanTreeVirtual } from "@/components/ui/span-tree-virtual";

/** Shared render context threaded to every row (kills per-node prop duplication). */
export interface SpanTreeRenderCtx {
  selectedId: string | null;
  collapsed: Set<string>;
  showMetrics?: boolean;
  bounds?: { startNs: bigint; endNs: bigint };
  onSelect: (id: string) => void;
  onToggle: (id: string) => void;
  renderBadge?: (span: TraceSpan) => ReactNode;
}

export interface SpanTreeProps extends Omit<SpanTreeRenderCtx, "onToggle"> {
  /** Root span of the trace. */
  root: TraceSpan;
  /** Collapse toggle (controlled). */
  onToggleCollapse: (id: string) => void;
  /** Visible-row count at/above which the virtualized path engages. Default 200. */
  virtualizeThreshold?: number;
  className?: string;
  "aria-label"?: string;
}

/**
 * SpanTree — an accessible, controllable tree of trace spans with full
 * WAI-ARIA APG TreeView semantics (treeitem / level / posinset / setsize /
 * selected / expanded / group). Renders recursively for small traces and
 * switches to a virtualized flat-list at/above `virtualizeThreshold`. The
 * container is keyboard-navigable (↑/↓ move, Home/End jump, Enter/Space
 * select). Fully controlled: selection + collapse live in the consumer.
 */
export function SpanTree({
  root,
  selectedId,
  onSelect,
  collapsed,
  onToggleCollapse,
  showMetrics = true,
  bounds,
  virtualizeThreshold = VIRTUALIZE_THRESHOLD,
  renderBadge,
  className,
  "aria-label": ariaLabel = "Trace span tree",
}: SpanTreeProps) {
  const flat = useMemo(() => flattenVisible(root, collapsed), [root, collapsed]);
  const virtualized = flat.length >= virtualizeThreshold;
  const ctx: SpanTreeRenderCtx = {
    selectedId,
    collapsed,
    showMetrics,
    bounds,
    onSelect,
    onToggle: onToggleCollapse,
    renderBadge,
  };

  // ↑/↓ move selection through the visible order; Home/End jump; Enter/Space (re)select.
  const onKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    const idx = flat.findIndex((f) => f.span.id === selectedId);
    const go = (i: number) => {
      const target = flat[i];
      if (target) onSelect(target.span.id);
    };
    if (e.key === "ArrowDown") {
      e.preventDefault();
      go(Math.min(idx + 1, flat.length - 1));
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      go(Math.max(idx - 1, 0));
    } else if (e.key === "Home") {
      e.preventDefault();
      go(0);
    } else if (e.key === "End") {
      e.preventDefault();
      go(flat.length - 1);
    } else if ((e.key === "Enter" || e.key === " ") && idx >= 0) {
      e.preventDefault();
      go(idx);
    }
  };

  return (
    <div
      // `role="tree"` is the correct WAI-ARIA pattern here; no native element expresses it.
      // (The `biome-ignore` this comment replaced no longer suppresses anything — Biome stopped
      // flagging the case, and an unused suppression is itself a lint error.)
      role="tree"
      data-slot="span-tree"
      aria-label={ariaLabel}
      // biome-ignore lint/a11y/noNoninteractiveTabindex: the tree is a composite widget owning roving focus
      tabIndex={0}
      onKeyDown={onKeyDown}
      className={cn("outline-none focus-visible:ring-2 focus-visible:ring-ring", className)}
    >
      {virtualized ? (
        <SpanTreeVirtual flat={flat} {...ctx} />
      ) : (
        <RecursiveNode span={root} depth={0} posinset={1} setsize={1} ctx={ctx} />
      )}
    </div>
  );
}

function RecursiveNode({
  span,
  depth,
  posinset,
  setsize,
  ctx,
}: {
  span: TraceSpan;
  depth: number;
  posinset: number;
  setsize: number;
  ctx: SpanTreeRenderCtx;
}) {
  const isCollapsed = ctx.collapsed.has(span.id);
  const children = span.children ?? [];
  return (
    <div>
      <SpanTreeRow
        span={span}
        depth={depth}
        selected={span.id === ctx.selectedId}
        collapsed={isCollapsed}
        hasChildren={children.length > 0}
        posinset={posinset}
        setsize={setsize}
        showMetrics={ctx.showMetrics}
        bounds={ctx.bounds}
        onSelect={ctx.onSelect}
        onToggle={ctx.onToggle}
        renderBadge={ctx.renderBadge}
      />
      {!isCollapsed && children.length > 0 ? (
        <div
          // biome-ignore lint/a11y/useSemanticElements: role="group" is the WAI-ARIA TreeView nesting contract
          role="group"
        >
          {children.map((c, i) => (
            <RecursiveNode
              key={`${i}-${c.id}`}
              span={c}
              depth={depth + 1}
              posinset={i + 1}
              setsize={children.length}
              ctx={ctx}
            />
          ))}
        </div>
      ) : null}
    </div>
  );
}

import { ChevronDown, ChevronRight } from "lucide-react";
import type { ReactNode } from "react";
import { cn } from "@/lib/cn";
import { computeBarLayout } from "@/lib/trace/bar-layout";
import { durationMs, formatDurationMs, isSpanError } from "@/lib/trace/duration";
import type { TraceSpan } from "@/lib/trace/types";
import { Badge } from "@/components/ui/badge";

export interface SpanTreeRowProps {
  span: TraceSpan;
  depth: number;
  selected: boolean;
  collapsed: boolean;
  hasChildren: boolean;
  posinset: number;
  setsize: number;
  showMetrics?: boolean;
  /** Optional trace window for the inline timeline bar. */
  bounds?: { startNs: bigint; endNs: bigint };
  onSelect: (id: string) => void;
  onToggle: (id: string) => void;
  renderBadge?: (span: TraceSpan) => ReactNode;
}

/** The single clickable row for a span — shared by the recursive and virtualized paths. */
export function SpanTreeRow({
  span,
  depth,
  selected,
  collapsed,
  hasChildren,
  posinset,
  setsize,
  showMetrics = true,
  bounds,
  onSelect,
  onToggle,
  renderBadge,
}: SpanTreeRowProps) {
  const dur = durationMs(span);
  const error = isSpanError(span.status);
  return (
    <div
      role="treeitem"
      data-slot="span-tree-row"
      aria-level={depth + 1}
      aria-posinset={posinset}
      aria-setsize={setsize}
      aria-selected={selected}
      aria-expanded={hasChildren ? !collapsed : undefined}
      className="flex items-center gap-2"
      style={{ paddingLeft: `${depth * 16}px` }}
    >
      {hasChildren ? (
        <button
          type="button"
          aria-label={collapsed ? `Expand ${span.name}` : `Collapse ${span.name}`}
          aria-expanded={!collapsed}
          onClick={() => onToggle(span.id)}
          className="shrink-0 rounded p-0.5 text-muted-foreground hover:bg-muted/50"
        >
          {collapsed ? (
            <ChevronRight className="h-3.5 w-3.5" />
          ) : (
            <ChevronDown className="h-3.5 w-3.5" />
          )}
        </button>
      ) : (
        <span className="w-4 shrink-0" aria-hidden="true" />
      )}
      <button
        type="button"
        tabIndex={-1}
        aria-current={selected ? "true" : undefined}
        onClick={() => onSelect(span.id)}
        className={cn(
          "flex min-w-0 flex-1 items-center gap-2 rounded-md py-1 pr-2 text-left text-body-sm hover:bg-muted/50",
          selected && "bg-muted font-medium",
        )}
      >
        <span className="min-w-0 truncate font-mono text-xs">{span.name}</span>
        {showMetrics && dur !== null ? (
          <span className="shrink-0 text-muted-foreground text-xs">{formatDurationMs(dur)}</span>
        ) : null}
        {span.model ? (
          <Badge variant="outline" className="shrink-0">
            {span.model}
          </Badge>
        ) : null}
        {showMetrics && (span.inputTokens !== undefined || span.outputTokens !== undefined) ? (
          <span className="shrink-0 text-muted-foreground text-xs">
            {span.inputTokens ?? 0}→{span.outputTokens ?? 0}
          </span>
        ) : null}
        {error ? (
          <Badge variant="destructive" className="shrink-0">
            error
          </Badge>
        ) : null}
        {renderBadge?.(span)}
        {bounds ? <InlineBar span={span} bounds={bounds} error={error} /> : null}
      </button>
    </div>
  );
}

/** Positioned timeline bar sized by `computeBarLayout`. Presentational (aria-hidden). */
function InlineBar({
  span,
  bounds,
  error,
}: {
  span: TraceSpan;
  bounds: { startNs: bigint; endNs: bigint };
  error: boolean;
}) {
  const { leftPct, widthPct, unbounded } = computeBarLayout(
    span.startTime,
    span.endTime,
    bounds.startNs,
    bounds.endNs,
  );
  return (
    <span
      className="relative ml-2 block h-4 min-w-[64px] flex-1 overflow-hidden rounded-sm bg-muted/30"
      aria-hidden="true"
    >
      <span
        data-slot="span-tree-bar"
        data-error={error ? "true" : undefined}
        data-unbounded={unbounded ? "true" : undefined}
        style={{ left: `${leftPct}%`, width: `max(${widthPct}%, 2px)` }}
        className={cn(
          "absolute top-0.5 bottom-0.5 rounded-sm",
          error ? "bg-destructive" : "bg-primary/60",
          unbounded && "border border-primary/60 border-dashed bg-transparent",
        )}
      />
    </span>
  );
}

import { useVirtualizer } from "@tanstack/react-virtual";
import { useEffect, useRef } from "react";
import type { FlatSpan } from "@/lib/trace/types";
import { SpanTreeRow } from "@/components/ui/span-tree-row";
import type { SpanTreeRenderCtx } from "@/components/ui/span-tree";

export interface SpanTreeVirtualProps extends SpanTreeRenderCtx {
  flat: FlatSpan[];
}

/** Virtualized flat-list tree (large traces at/above the threshold), reusing @tanstack/react-virtual. */
export function SpanTreeVirtual({
  flat,
  selectedId,
  collapsed,
  showMetrics,
  bounds,
  onSelect,
  onToggle,
  renderBadge,
}: SpanTreeVirtualProps) {
  const parentRef = useRef<HTMLDivElement>(null);
  const virtualizer = useVirtualizer({
    count: flat.length,
    getScrollElement: () => parentRef.current,
    estimateSize: () => 32,
    overscan: 20,
    // A default viewport so rows render before the real ResizeObserver measures the element
    // (SSR/jsdom have no layout). The real observer overrides this in the browser.
    initialRect: { width: 320, height: 640 },
  });

  // Scroll the selected row into view when selection changes.
  // biome-ignore lint/correctness/useExhaustiveDependencies: intentionally keyed on selectedId only
  useEffect(() => {
    const index = flat.findIndex((f) => f.span.id === selectedId);
    if (index >= 0) virtualizer.scrollToIndex(index, { align: "center", behavior: "auto" });
  }, [selectedId]);

  return (
    <div ref={parentRef} data-slot="span-tree-virtual" className="max-h-[70vh] overflow-auto">
      <div style={{ height: virtualizer.getTotalSize(), position: "relative", width: "100%" }}>
        {virtualizer.getVirtualItems().map((vi) => {
          const row = flat[vi.index];
          if (!row) return null;
          return (
            <div
              key={`${vi.index}-${row.span.id}`}
              data-index={vi.index}
              ref={virtualizer.measureElement}
              style={{
                position: "absolute",
                top: 0,
                left: 0,
                width: "100%",
                transform: `translateY(${vi.start}px)`,
              }}
            >
              <SpanTreeRow
                span={row.span}
                depth={row.depth}
                selected={row.span.id === selectedId}
                collapsed={collapsed.has(row.span.id)}
                hasChildren={(row.span.children?.length ?? 0) > 0}
                posinset={vi.index + 1}
                setsize={flat.length}
                showMetrics={showMetrics}
                bounds={bounds}
                onSelect={onSelect}
                onToggle={onToggle}
                renderBadge={renderBadge}
              />
            </div>
          );
        })}
      </div>
    </div>
  );
}
